```suggestion
    constexpr int kMeasureShapeOpts = Feature::NeedSubElement | Feature::ResolveLink | Feature::Transform;
    TopoDS_Shape shape = Part::Feature::getShape(ob, subName, nullptr, nullptr, kMeasureShapeOpts);
```

